package geography_test

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"os"
	"testing"

	"github.com/yomezza/cosmosimulator/internal/geography"
	"github.com/yomezza/cosmosimulator/internal/universe"
)

// Hashes were generated by the unmodified v0.13.0 server at d52eb29.
// This protects persisted geography and deterministic systems across package moves.
func TestPreRefactorGeographyCompatibility(t *testing.T) {
	raw, err := os.ReadFile("testdata/v0.13.0-hashes.json")
	if err != nil {
		t.Fatal(err)
	}
	var expected map[string]string
	if err = json.Unmarshal(raw, &expected); err != nil {
		t.Fatal(err)
	}
	values := map[string]any{"galaxy": universe.Generate(128, 20261026)}
	for _, kind := range []string{"Садовый мир", "Ледяная", "Каменистая", "Вулканическая"} {
		p := universe.Planet{ID: 1, Name: "Compatibility", Kind: kind, Mass: 1, Gravity: 1, Temperature: 288}
		surface := geography.Generate(p, "refactor-compatibility", 100)
		values[kind] = surface
		samples := [][2]float64{}
		for _, point := range [][2]float64{{-1, -1}, {0, 0}, {surface.Width * .33, surface.Height * .66}, {surface.Width, surface.Height}} {
			height, water := surface.Sample(point[0], point[1])
			samples = append(samples, [2]float64{height, float64(water)})
		}
		values["samples/"+kind] = samples
	}
	for key, value := range values {
		t.Run(key, func(t *testing.T) {
			raw, err := json.Marshal(value)
			if err != nil {
				t.Fatal(err)
			}
			sum := sha256.Sum256(raw)
			if got := hex.EncodeToString(sum[:]); got != expected[key] {
				t.Fatalf("canonical generation changed: %s, want %s", got, expected[key])
			}
		})
	}
}
